const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const laPoint = ee.Geometry.Point(-118.2436826460509, 33.97811334086217);
    const sdPoint = ee.Geometry.Point(-117.15380986802357, 32.7358717958782);
    const startDate = '2018-01-01';
    const endDate = '2019-12-31';
    const band = 'tropospheric_NO2_column_number_density';

    // 2. Data Acquisition & Masking
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
        .select([band, 'qa_value'])
        .filterDate(startDate, endDate);

    // Use QA band to mask low quality pixels (e.g. cloud-covered)
    const maskLowQuality = function(image) {
        return image.updateMask(image.select('qa_value').gte(0.75));
    };
    const maskedCollection = collection.map(maskLowQuality);

    // 3. Data Availability Check
    const laCollection = maskedCollection.filterBounds(laPoint);
    const sdCollection = maskedCollection.filterBounds(sdPoint);

    const laSize = laCollection.size().getInfo();
    const sdSize = sdCollection.size().getInfo();

    if (laSize === 0 || sdSize === 0) {
        console.log(`Image count LA: ${laSize}`);
        console.log(`Image count SD: ${sdSize}`);
        console.log("Empty collection for one or both locations.");
        console.log("C1");
        return;
    }

    // 4. Processing & Calculation
    const laMeanImage = laCollection.select(band).mean();
    const sdMeanImage = sdCollection.select(band).mean();

    // Reducer arguments
    const reducerArgs = {
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        scale: 1000,
        maxPixels: 1e9
    };

    // Extract values
    const laStats = laMeanImage.reduceRegion({...reducerArgs, geometry: laPoint }).getInfo();
    const sdStats = sdMeanImage.reduceRegion({...reducerArgs, geometry: sdPoint }).getInfo();

    const laValue = laStats[band + '_mean'];
    const laCount = laStats[band + '_count'];
    const sdValue = sdStats[band + '_mean'];
    const sdCount = sdStats[band + '_count'];

    // 5. Validation & Final Answer
    if (laCount === 0 || sdCount === 0) {
        console.log(`LA Valid Pixels: ${laCount}`);
        console.log(`SD Valid Pixels: ${sdCount}`);
        console.log("No valid pixels after cloud/QA masking for one or both locations.");
        console.log("C2");
        return;
    }

    if (laValue === null || sdValue === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    // Print evidence (values are in mol/m^2)
    console.log(`Los Angeles Average NO2 (mol/m^2): ${laValue.toExponential(4)}`);
    console.log(`San Diego Average NO2 (mol/m^2): ${sdValue.toExponential(4)}`);

    if (laValue > sdValue) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    try {
        await runAnalysis();
    } catch (e) {
        console.error(`Error: ${e.toString()}`);
        console.log("D");
    }
}

initEE();
